INSERT INTO psppv2_form_assets (key, label, content_type, bytes, data_b64, source_url, updated_at) SELECT 'contract-ccmc-2027', 'Boudoir Session Contract - Charity Calendar Model Call', 'text/markdown', octet_length(t.txt), replace(encode(convert_to(t.txt,'UTF8'),'base64'), chr(10), ''), 'derived from contract-giveaway-2026, approved by Jessica 2026-10-24', now() FROM (SELECT replace(replace(replace(replace(replace(replace(replace(convert_from(decode(g.data_b64,'base64'),'UTF8'), ('The Client shall make a booking retainer of $197 for the Photographer to perform the services specified herein. Upon payment, the Photographer will reserve the time and date agreed upon by both parties. Client agrees that this retainer is earned by the Photographer when paid, and is remitted in consideration of the experience, reputation, skill of the Photographer, and in consideration of the inability of the Photographer to schedule other clients during this time. On signing of this agreement by both parties hereto, the Photographer will reserve the date and times ranges agreed upon and will not make another reservation for the specific date and time frame. For this reason, all retainers are non-refundable even if the date is changed or if the session becomes cancelled for any reason.'), ('The Client shall make a booking retainer of $99 for the Photographer to perform the services specified herein. Upon payment, the Photographer will reserve the time and date agreed upon by both parties. Client agrees that this retainer is earned by the Photographer when paid, and is remitted in consideration of the experience, reputation, skill of the Photographer, and in consideration of the inability of the Photographer to schedule other clients during this time. On signing of this agreement by both parties hereto, the Photographer will reserve the date and times ranges agreed upon and will not make another reservation for the specific date and time frame. For this reason, all retainers are non-refundable even if the date is changed or if the session becomes cancelled for any reason.')), ('The Session Fee of $197 for the boudoir session giveaway is imposed and paid by the client to retain the client''s session date and is not applicable to any product purchase made by the client.  The Client understands and agrees that no images, digital or physical, are included in the cost of the retainer. All images, both digital and physical, will be available for pre-purchase or purchase upon completion of the session. Any additional photography coverage beyond the terms listed at the top of this contract will be billed at $100 per hour. The session fee and retainer does not include any images whatsoever.'), ('The Session Fee of $99 for the Charity Calendar Model Call is imposed and paid by the client to retain the client''s session date, is non-refundable, and is not applicable to any product purchase made by the client.  The Client understands and agrees that no images, digital or physical, are included in the cost of the retainer. All images, both digital and physical, will be available for pre-purchase or purchase upon completion of the session. Any additional photography coverage beyond the terms listed at the top of this contract will be billed at $100 per hour. The session fee and retainer does not include any images whatsoever.')), ('The charges in this Contract are based on the Photographer''s Standard Price List. The price list was discussed verbally between THE PHOTOGRAPHER and THE CLIENT prior to booking the session. The Photographer provided the Client with starting prices verbally over the phone prior to accepting payment for the retainer fee, to ensure that the Client approves and understands generalized investment for print purchases. Contents included in any package are not redeemable as cash or as a deduction from package price. All purchases over the amount of included will be billed to Client. Products are subject to availability from the manufacturer. Client will only receive images that are purchased, all unpurchased images are immediately purged upon completion of the Reveal & Ordering appointment.'), ('The charges in this Contract are based on the Photographer''s Standard Price List. The Photographer''s starting prices and minimum product investment were published on the Charity Calendar Model Call landing page for the Client''s review prior to booking, and THE CLIENT reviewed that information prior to submitting the retainer. The Photographer provided the Client with those starting prices in writing on that page prior to accepting payment for the retainer fee, to ensure that the Client approves and understands generalized investment for print purchases. Contents included in any package are not redeemable as cash or as a deduction from package price. All purchases over the amount of included will be billed to Client. Products are subject to availability from the manufacturer. Client will only receive images that are purchased, all unpurchased images are immediately purged upon completion of the Reveal & Ordering appointment.')), ('BOUDOIR SESSION GIVEAWAY:  ' || chr(10) || 'The Boudoir Session Giveaway shall only include a $500 discounted Session Fee and $500 Collection Credit.  No products or services are included with the giveaway.  All other products must be purchased separately.'), ('CHARITY CALENDAR MODEL CALL:  ' || chr(10) || 'The Charity Calendar Model Call shall only include the $99 Session Fee and $500 off the Client''s collection, already applied to the collection prices shown at booking.  No products or services are included with the model call.  All other products must be purchased separately.' || chr(10) || '2027 CHARITY CALENDAR ENTRY:' || chr(10) || 'Entering the Client''s images in the 2027 Charity Calendar is optional and is decided by the Client at her Image Reveal & Ordering Appointment. Calendar entry requires the Client to sign the Photographer''s standard Model Release at or after the Image Reveal & Ordering Appointment. The $500 discount applies whether or not the Client''s images are entered in the calendar. Only sessions held through October 2027 are eligible for the calendar' || chr(59) || ' sessions held November 2027 through March 2028 receive the same Charity Calendar Model Call pricing but are not eligible for the calendar. No images will be shared publicly without the Client''s written permission.')), ('THE CLIENT agrees that the paid session fee retainer of $197 is non-transferable in order to hold a reservation/date with STUDIO.  Any change of date requires a newly signed Contract and retainer. '), ('THE CLIENT agrees that the paid session fee retainer of $99 is non-transferable in order to hold a reservation/date with STUDIO.  Any change of date requires a newly signed Contract and retainer. ')), ('I have been educated on the product investment and understand that the minimum product investment in my boudoir portraits with this Boudoir Session Giveaway is $750 and includes 3 digital images.'), ('I have been educated on the product investment and understand that the minimum product investment in my boudoir portraits with this Charity Calendar Model Call is $750 and includes 3 digital images.')), ('I understand the Boudoir Session Giveaway only includes a $500 discounted Session Fee and $500 Collection Credit. No products or services are included with the giveaway and all other products must be purchased separately.*'), ('I understand the Charity Calendar Model Call only includes the $99 Session Fee I paid to reserve my date and $500 off my collection, already taken off every collection price. No products or services are included with the model call, and all other products must be purchased separately.*' || chr(10) || 'I understand that entering my images in the 2027 Charity Calendar is optional and is decided at my Image Reveal & Ordering Appointment, that it requires me to sign the standard Model Release, and that my $500 discount applies whether or not my images are entered. Sessions held after October 2027 are not eligible for the calendar, and my images will never be shared publicly without my written permission.*')) AS txt FROM psppv2_form_assets g WHERE g.key='contract-giveaway-2026') t RETURNING key, bytes, md5(convert_from(decode(data_b64,'base64'),'UTF8')) AS m